function promiseAll(arr) {
  return new Promise((resolve, reject) => {
    const out = new Array(arr.length);   // preallocate so order is preserved
    let done = 0;
    if (arr.length === 0) return resolve(out);
    arr.forEach((item, i) => {
      Promise.resolve(item)               // lift non-promises into the chain
        .then(v => {
          out[i] = v;
          if (++done === arr.length) resolve(out);
        })
        .catch(reject);                   // first rejection wins
    });
  });
}

